"""Release 1.72.577 GardenTools: one hunk on the LIVE inc/instruments.php (the require of inc/garden-tools.php). Generated by make_deploy577.py."""
RELS = ['inc/instruments.php']
HUNKS = {'inc/instruments.php': [("if ( file_exists( __DIR__ . '/asbestos-tools.php' ) ) { require_once __DIR__ . '/asbestos-tools.php'; }", "if ( file_exists( __DIR__ . '/asbestos-tools.php' ) ) { require_once __DIR__ . '/asbestos-tools.php'; }\n\n/* 1.72.577 (HAD-669): the Tel Aviv garden-apartments tools (gdnworth, gdnmap, gdnstreet, gdnground) and [nadlan_garden_listings]; loaded only if present */\nif ( file_exists( __DIR__ . '/garden-tools.php' ) ) { require_once __DIR__ . '/garden-tools.php'; }", 1)]}


def apply(rel, txt):
    if rel not in HUNKS:
        raise SystemExit('ashira_577: no hunk on ' + rel)
    for old, new, n in HUNKS[rel]:
        if new in txt:
            raise SystemExit('ashira_577: the live %s already holds the new text' % rel)
        k = txt.count(old)
        if k != n:
            raise SystemExit('ashira_577: anchor x%d (want %d) in the live %s' % (k, n, rel))
        txt = txt.replace(old, new)
    return txt
